insert into public.departments(campus_id,code,name) select c.id,v.code,v.name from public.campuses c cross join (values ('cse','Computer Science'),('aids','AI & Data Science'),('ise','Information Science'),('ece','Electronics & Communication'),('eee','Electrical & Electronics'),('mech','Mechanical'),('civil','Civil'),('mba','MBA')) v(code,name) where c.code='supercampus-main' on conflict(campus_id,code) do update set name=excluded.name;
